mapper.insert:

	SELECT SEQ_NOTICE.NEXTVAL FROM DUAL

INSERT INTO NOTICE (
	NOTICE_ID, ADMIN_ID, TITLE, CONTENT, PINNED_YN, STATUS, HIT_COUNT, CREATED_AT, UPDATED_AT
) VALUES (
	#{noticeId}, #{adminId}, #{title}, #{content}, NVL(#{pinnedYn, jdbcType=VARCHAR}, 'N'), #{status}, 0, SYSTIMESTAMP, SYSTIMESTAMP
)

INSERT INTO NOTICE_FILE (
	NOTICE_FILE_ID, NOTICE_ID, ORIGINAL_FILE_NAME, FILE_PATH
) VALUES (
	SEQ_NOTICE_FILE.NEXTVAL, #{noticeId}, #{originalFileName}, #{filePath}
)
